// Provisional viewer-facing comedy styles inferred from editorial cue labels.
const topicFromCue = (cue: string) => {
  if (/雙關|字義|語言/.test(cue)) return "語言雙關"
  if (/角色|模仿|職業|致詞/.test(cue)) return "角色扮演"
  if (/升級|迴圈|推演|跳躍|混搭/.test(cue)) return "越講越荒謬"
  if (/錯位|誤會/.test(cue)) return "誤會連發"
  if (/反轉|反差|揭露|落差|收尾|落空/.test(cue)) return "意外反轉"
  return "一本正經亂講"
}

